export function expandPriorityFood(existingProducts) {
  const expanded = recipes.map(({ existingId, variants, ...recipe }) => {
    const previous = existingProducts.find(p => p.id === existingId);
    const base = { ...recipe, ...previous, image: recipe.image, researchRecipeId: recipe.researchRecipeId,
      foodType: recipe.foodType, prioritySelection: true, optionLabel: 'Фасовка' };
    const packs = variants.map(v => {
      const keepsOriginal = previous?.packageWeightKg === v.packageWeightKg;
      return { ...base, ...v, line: base.brand + ' · ' + v.weight,
        ...(keepsOriginal ? { price: previous.price, priceStatus: previous.priceStatus, ean: previous.ean,
          supplier: previous.supplier, retailPrice: previous.retailPrice } : {}) };
    });
    const originalPack = previous && packs.find(v => v.packageWeightKg === previous.packageWeightKg);
    const selected = originalPack || packs.find(v => v.id === recipe.defaultVariantId) || packs[0];
    const weight = packs.length > 1 ? packs[0].weight + ' - ' + packs.at(-1).weight : selected.weight;
    return { ...base, defaultVariantId: selected.id, price: selected.price, priceStatus: selected.priceStatus,
      weight, packageWeightKg: selected.packageWeightKg, ean: selected.ean, retailPrice: selected.retailPrice,
      sizes: packs.map(v => v.label), variants: packs };
  });
  const products = [...existingProducts.map(p => expanded.find(r => r.id === p.id) || p),
    ...expanded.filter(p => !existingProducts.some(e => e.id === p.id))];
  // Distribute brands across the catalog so the large Royal Canin range does not fill the first screens
  const brands = [...new Set(products.map(p => p.brand))];
  const groups = brands.map(brand => products.filter(p => p.brand === brand));
  return Array.from({ length: Math.max(...groups.map(g => g.length)) }, (_, i) => groups.map(g => g[i]).filter(Boolean)).flat();
}
